#!/usr/bin/env node

import { randomUUID } from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import {
  SessionHostClient,
  formatRuntimeOwner,
  getDefaultSessionHostEndpoint,
  resolveAttachableRuntimeRecord,
  resolveInstanceConfigDir,
  resolveRuntimeRecord,
  resolveSessionHostIpcKey,
  type SessionHostEvent,
  type SessionHostRecord,
} from '@adhdev/session-host-core';
import { resolveGuardianArtifact, type GuardianArtifactPins } from './guardian-artifact.js';
import {
  SessionHostServer,
  isManagedSessionHostCommandLine,
  sessionHostInstanceArg,
} from './server.js';
import { startThreadpoolWatchdog, writeStderrLineSync } from './threadpool-watchdog.js';

export {
  SessionHostServer,
  isManagedSessionHostCommandLine,
  readVerifiedReplacementProvenance,
  sessionHostInstanceArg,
} from './server.js';
export { startThreadpoolWatchdog } from './threadpool-watchdog.js';
export type {
  SessionHostReplacementProvenance,
  SessionHostServerOptions,
} from './server.js';
export { resolveGuardianArtifact } from './guardian-artifact.js';
export type { GuardianArtifactPins } from './guardian-artifact.js';
export type { HostUpgradeBinding } from './upgrade-lease.js';

const SESSION_HOST_APP_NAME = process.env.ADHDEV_SESSION_HOST_NAME || 'adhdev';
const SHUTDOWN_DEADLINE_MS = 10_000;

// Instance identity comes from the parent daemon's pinned env
// (ADHDEV_CONFIG_DIR — see managed-host buildEnv). The endpoint, pid file, and
// storage root all derive from that ONE resolution so the host process lives
// entirely inside its own instance's namespace: two simultaneous instances
// (stable/preview/standalone/custom) can never attach to, kill, or persist
// over each other's session host. The default instance yields the legacy
// un-suffixed socket and `<home>/.adhdev` paths, byte-identical to before.
const INSTANCE_CONFIG_DIR = resolveInstanceConfigDir(process.env);
const INSTANCE_IPC_KEY = resolveSessionHostIpcKey(INSTANCE_CONFIG_DIR);

function getSessionHostEndpoint() {
  return getDefaultSessionHostEndpoint(SESSION_HOST_APP_NAME, { ipcKey: INSTANCE_IPC_KEY });
}

function getSessionHostStorageRoot(): string {
  return path.join(INSTANCE_CONFIG_DIR, 'session-host', SESSION_HOST_APP_NAME);
}

export function getSessionHostReplacementProvenanceFile(
  appName: string,
  configDir: string = INSTANCE_CONFIG_DIR,
): string {
  const dir = configDir;
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, `${appName}-session-host-replacement.json`);
}

export function removeSessionHostReplacementProvenance(
  appName: string,
  configDir: string = INSTANCE_CONFIG_DIR,
): void {
  try {
    const provenanceFile = path.join(configDir, `${appName}-session-host-replacement.json`);
    if (fs.existsSync(provenanceFile)) {
      fs.unlinkSync(provenanceFile);
    }
  } catch {
    // noop
  }
}

function getSessionHostPidFile(appName: string): string {
  const dir = INSTANCE_CONFIG_DIR;
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, `${appName}-session-host.pid`);
}

function writeSessionHostPid(appName: string): void {
  fs.writeFileSync(getSessionHostPidFile(appName), String(process.pid), 'utf8');
}

function removeSessionHostPid(appName: string): void {
  try {
    const pidFile = getSessionHostPidFile(appName);
    if (!fs.existsSync(pidFile)) return;
    const recordedPid = Number.parseInt(fs.readFileSync(pidFile, 'utf8').trim(), 10);
    if (Number.isFinite(recordedPid) && recordedPid !== process.pid) return;
    fs.unlinkSync(pidFile);
  } catch {
    // noop
  }
}

function parseArgs(argv: string[]) {
  const [command, ...rest] = argv;
  const readOnly = rest.includes('--read-only');
  const takeover = rest.includes('--takeover');
  const showAll = rest.includes('--all');
  const instanceKeyArgs = rest.filter((arg) => arg.startsWith('--instance-config-key='));
  const positional = rest.filter(
    (arg) =>
      arg !== '--read-only'
      && arg !== '--takeover'
      && arg !== '--all'
      && !arg.startsWith('--instance-config-key='),
  );
  return {
    command: command || 'serve',
    positional,
    readOnly,
    takeover,
    showAll,
    instanceKeyArgs,
  };
}

async function runServer(instanceKeyArgs: string[] = []): Promise<void> {
  if (
    instanceKeyArgs.length > 1
    || (instanceKeyArgs.length === 1 && instanceKeyArgs[0] !== sessionHostInstanceArg(INSTANCE_CONFIG_DIR))
  ) {
    throw new Error('session_host_instance_config_key_mismatch');
  }
  let upgradeBinding;
  const pinFile = process.env.ADHDEV_WORKER_GUARDIAN_PINS_FILE;
  if (pinFile) {
    const stat = fs.lstatSync(pinFile);
    if (process.platform !== 'darwin' || fs.realpathSync(pinFile) !== pinFile || !stat.isFile() || stat.uid !== process.getuid?.() || (stat.mode & 0o077)) throw new Error('guardian_launch_pins_untrusted');
    const pins = JSON.parse(fs.readFileSync(pinFile, 'utf8')) as GuardianArtifactPins;
    if (pins.nodePath !== fs.realpathSync(process.execPath) || pins.hostEntryPath !== fs.realpathSync(process.argv[1]) ||
        pins.stateDir !== path.join(INSTANCE_CONFIG_DIR, 'session-host')) throw new Error('guardian_launch_executable_or_instance_mismatch');
    upgradeBinding = resolveGuardianArtifact(pins);
  }
  const endpoint = getSessionHostEndpoint();
  const server = new SessionHostServer({
    appName: SESSION_HOST_APP_NAME,
    upgradeBinding,
    endpoint,
    storageRootDir: getSessionHostStorageRoot(),
    instanceConfigDir: INSTANCE_CONFIG_DIR,
    pidFilePath: getSessionHostPidFile(SESSION_HOST_APP_NAME),
  });
  await server.start();
  writeSessionHostPid(SESSION_HOST_APP_NAME);

  const shutdown = async () => {
    // A wedged thread pool can leave stop() pending forever; the 2026-10-21
    // host ignored SIGTERM this way and needed SIGKILL. Exit regardless.
    const deadline = setTimeout(() => {
      writeStderrLineSync(`[session-host] stop() did not finish within ${SHUTDOWN_DEADLINE_MS / 1000}s; exiting anyway.`);
      removeSessionHostPid(SESSION_HOST_APP_NAME);
      process.exit(1);
    }, SHUTDOWN_DEADLINE_MS);
    deadline.unref?.();
    await server.stop();
    removeSessionHostPid(SESSION_HOST_APP_NAME);
    process.exit(0);
  };
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);

  // Exiting ends every hosted session, but in this state none of them can take
  // input anyway; the daemon respawns the host as soon as the socket drops.
  startThreadpoolWatchdog({
    onStall: (stalledForMs) => {
      writeStderrLineSync(
        `[session-host] libuv thread pool made no progress for ${Math.round(stalledForMs / 1000)}s ` +
          '(PTY writes cannot complete); exiting so the daemon respawns the host.',
      );
      try {
        server.flushAllPersistence();
      } catch {
        // noop — exiting regardless
      }
      removeSessionHostPid(SESSION_HOST_APP_NAME);
      process.exit(1);
    },
  });

  // Fallback: flush persistence on any exit (covers Windows where SIGTERM is unsupported)
  process.on('exit', () => {
    server.flushAllPersistence();
    removeSessionHostPid(SESSION_HOST_APP_NAME);
  });

  // Keep the host alive; IPC transport wiring comes next.
  await new Promise<void>(() => {});
}

async function listRuntimes(showAll = false): Promise<void> {
  const client = new SessionHostClient({ endpoint: getSessionHostEndpoint() });
  try {
    const response = await client.request<SessionHostRecord[]>({
      type: 'list_sessions',
      payload: {},
    });
    if (!response.success) {
      throw new Error(response.error || 'Failed to list runtimes');
    }
    const runtimes = (response.result || []).filter((runtime: SessionHostRecord) => showAll || runtime.lifecycle !== 'stopped');
    if (runtimes.length === 0) {
      console.log('No runtimes.');
      return;
    }
    console.log('runtimeKey\tlifecycle\towner\tworkspace\tid\tdisplayName');
    for (const runtime of runtimes) {
      console.log([
        runtime.runtimeKey,
        runtime.lifecycle,
        formatRuntimeOwner(runtime),
        runtime.workspaceLabel,
        runtime.sessionId,
        runtime.displayName,
      ].join('\t'));
    }
  } finally {
    await client.close().catch(() => {});
  }
}

async function attachRuntime(target: string, readOnly = false, takeover = false): Promise<void> {
  const client = new SessionHostClient({ endpoint: getSessionHostEndpoint() });
  const clientId = `local-terminal-${process.pid}-${randomUUID().slice(0, 8)}`;
  let lastSeq = 0;
  let restoredRawMode = false;
  let runtimeId = '';
  let localReadOnly = readOnly;

  const cleanup = async () => {
    process.stdout.off('resize', handleResize);
    process.stdin.off('data', handleInput);
    process.stdin.pause();
    if (process.stdin.isTTY && restoredRawMode) {
      process.stdin.setRawMode(false);
    }
    await client.request({
      type: 'release_write',
      payload: {
        sessionId: runtimeId,
        clientId,
      },
    }).catch(() => ({ success: false }));
    await client.request({
      type: 'detach_session',
      payload: {
        sessionId: runtimeId,
        clientId,
      },
    }).catch(() => ({ success: false }));
    await client.close().catch(() => {});
  };

  const handleResize = () => {
    void client.request({
      type: 'resize_session',
      payload: {
        sessionId: runtimeId,
        cols: process.stdout.columns || 80,
        rows: process.stdout.rows || 24,
      },
    }).catch(() => ({ success: false }));
  };

  const sendInputWithTakeover = async (data: string) => {
    let response = await client.request({
      type: 'send_input',
      payload: {
        sessionId: runtimeId,
        clientId,
        data,
      },
    });
    if (!response.success && response.error?.startsWith('Write owned by ')) {
      const ownerResponse = await client.request<SessionHostRecord>({
        type: 'acquire_write',
        payload: {
          sessionId: runtimeId,
          clientId,
          ownerType: 'user',
          force: true,
        },
      });
      if (ownerResponse.success && ownerResponse.result) {
        response = await client.request({
          type: 'send_input',
          payload: {
            sessionId: runtimeId,
            clientId,
            data,
          },
        });
        if (response.success) {
          process.stderr.write(`Took control of ${ownerResponse.result.runtimeKey}.\n`);
        }
      }
    }
    return response;
  };

  const handleInput = (chunk: Buffer) => {
    if (!localReadOnly && chunk.length === 1 && chunk[0] === 0x1d) {
      void cleanup().finally(() => process.exit(0));
      return;
    }
    if (localReadOnly) return;
    void sendInputWithTakeover(chunk.toString('utf8')).catch(() => ({ success: false }));
  };

  try {
    if (readOnly && takeover) {
      throw new Error('Use either --read-only or --takeover, not both');
    }

    const listResponse = await client.request<SessionHostRecord[]>({
      type: 'list_sessions',
      payload: {},
    });
    if (!listResponse.success || !listResponse.result) {
      throw new Error(listResponse.error || 'Failed to list runtimes');
    }
    let runtimeRecord = resolveAttachableRuntimeRecord(listResponse.result, target);
    runtimeId = runtimeRecord.sessionId;

    if (runtimeRecord.lifecycle === 'interrupted' && !readOnly) {
      const resumeResponse = await client.request<SessionHostRecord>({
        type: 'resume_session',
        payload: {
          sessionId: runtimeId,
        },
      });
      if (resumeResponse.success && resumeResponse.result) {
        runtimeRecord = resumeResponse.result;
      } else {
        process.stderr.write(
          `Runtime ${runtimeRecord.runtimeKey} could not be resumed automatically: ${resumeResponse.error || 'unknown error'}\n`,
        );
      }
    }

    let effectiveReadOnly = readOnly;
    if (!effectiveReadOnly && runtimeRecord.writeOwner && runtimeRecord.writeOwner.clientId !== clientId && !takeover) {
      process.stderr.write(
        `Runtime ${runtimeRecord.runtimeKey} is currently owned by ${runtimeRecord.writeOwner.clientId}; first input will take control here.\n`,
      );
    }
    localReadOnly = effectiveReadOnly;

    const attachResponse = await client.request<SessionHostRecord>({
      type: 'attach_session',
      payload: {
        sessionId: runtimeId,
        clientId,
        clientType: 'local-terminal',
        readOnly: effectiveReadOnly,
      },
    });
    if (!attachResponse.success) {
      throw new Error(attachResponse.error || `Failed to attach runtime ${runtimeId}`);
    }
    const attachedRecord = attachResponse.result || null;

    if (!effectiveReadOnly && takeover) {
      const ownerResponse = await client.request<SessionHostRecord>({
        type: 'acquire_write',
        payload: {
          sessionId: runtimeId,
          clientId,
          ownerType: 'user',
          force: takeover,
        },
      });
      if (!ownerResponse.success) {
        throw new Error(ownerResponse.error || `Failed to acquire write owner for runtime ${runtimeId}`);
      }
    }

    const snapshotResponse = await client.request<{ seq: number; text: string; truncated: boolean; cols?: number; rows?: number }>({
      type: 'get_snapshot',
      payload: { sessionId: runtimeId },
    });
    if (!snapshotResponse.success) {
      throw new Error(snapshotResponse.error || `Failed to read runtime snapshot ${runtimeId}`);
    }
    lastSeq = snapshotResponse.result?.seq || 0;
    if (snapshotResponse.result?.text) {
      process.stdout.write(snapshotResponse.result.text);
    }
    if (attachedRecord?.lifecycle === 'stopped' || attachedRecord?.lifecycle === 'failed' || attachedRecord?.lifecycle === 'interrupted') {
      process.stderr.write(`Runtime ${attachedRecord.runtimeKey} is already ${attachedRecord.lifecycle}. Detached after snapshot.\n`);
      await cleanup();
      return;
    }

    const stopSignals = ['SIGINT', 'SIGTERM', 'SIGHUP'] as const;
    const signalHandlers = stopSignals.map((signal) => {
      const handler = () => {
        void cleanup().finally(() => process.exit(0));
      };
      process.on(signal, handler);
      return { signal, handler };
    });

    const unsubscribe = client.onEvent((event: SessionHostEvent) => {
      if (!('sessionId' in event)) return;
      if (event.sessionId !== runtimeId) return;
      if (event.type === 'session_output') {
        if (event.seq <= lastSeq) return;
        lastSeq = event.seq;
        process.stdout.write(event.data);
        return;
      }
      if (event.type === 'session_exit') {
        void cleanup().finally(() => {
          for (const { signal, handler } of signalHandlers) {
            process.off(signal, handler);
          }
          unsubscribe();
          process.exit(event.exitCode ?? 0);
        });
      }
    });

    process.stdout.on('resize', handleResize);
    process.stdin.on('data', handleInput);
    process.stdin.resume();
    if (process.stdin.isTTY) {
      process.stdin.setRawMode(true);
      restoredRawMode = true;
    }
    handleResize();
    if (!effectiveReadOnly) {
      process.stderr.write(`Attached to runtime ${attachedRecord?.runtimeKey || runtimeId}. Press Ctrl+] to detach.\n`);
    } else {
      process.stderr.write(`Attached to runtime ${attachedRecord?.runtimeKey || runtimeId} (read-only).\n`);
    }
    await new Promise<void>(() => {});
  } catch (error) {
    await cleanup().catch(() => {});
    throw error;
  }
}

async function main(): Promise<void> {
  const { command, positional, readOnly, takeover, showAll, instanceKeyArgs } = parseArgs(process.argv.slice(2));
  if (command === 'serve') {
    await runServer(instanceKeyArgs);
    return;
  }
  if (command === 'list') {
    await listRuntimes(showAll);
    return;
  }
  if (command === 'attach') {
    const target = positional[0];
    if (!target) {
      throw new Error('runtime target is required: adhdev-sessiond attach <runtimeId|runtimeKey>');
    }
    await attachRuntime(target, readOnly, takeover);
    return;
  }
  if (command === 'resume') {
    const target = positional[0];
    if (!target) {
      throw new Error('runtime target is required: adhdev-sessiond resume <runtimeId|runtimeKey>');
    }
    const client = new SessionHostClient({ endpoint: getSessionHostEndpoint() });
    try {
      const listResponse = await client.request<SessionHostRecord[]>({ type: 'list_sessions', payload: {} });
      if (!listResponse.success || !listResponse.result) {
        throw new Error(listResponse.error || 'Failed to list runtimes');
      }
      const runtimeRecord = resolveRuntimeRecord(listResponse.result, target);
      const resumeResponse = await client.request<SessionHostRecord>({
        type: 'resume_session',
        payload: {
          sessionId: runtimeRecord.sessionId,
        },
      });
      if (!resumeResponse.success || !resumeResponse.result) {
        throw new Error(resumeResponse.error || `Failed to resume runtime ${runtimeRecord.runtimeKey}`);
      }
      console.log(`Resumed ${resumeResponse.result.runtimeKey} (${resumeResponse.result.sessionId})`);
    } finally {
      await client.close().catch(() => {});
    }
    return;
  }
  throw new Error(`Unknown command: ${command}`);
}

// Swallowing uncaught exceptions keeps a transient native fault (e.g. node-pty on
// Windows) from killing sessions that are otherwise healthy. Swallowing them
// *without limit* turns a permanently broken process into a zombie service that
// still holds the socket and pid file while failing every request. So the intent
// is preserved with a bound: tolerate bursts, exit once the process is clearly
// wedged rather than pretending to serve.
const UNCAUGHT_EXCEPTION_WINDOW_MS = 60_000;
const UNCAUGHT_EXCEPTION_LIMIT = 10;

export function createUncaughtExceptionLimiter(
  windowMs = UNCAUGHT_EXCEPTION_WINDOW_MS,
  limit = UNCAUGHT_EXCEPTION_LIMIT,
) {
  // null (not 0) marks "no window yet" — 0 is a valid timestamp, and using it as
  // the sentinel would reset the window on every call in a 0-based clock.
  let windowStartedAt: number | null = null;
  let countInWindow = 0;
  return function shouldExit(now: number): { exit: boolean; countInWindow: number } {
    if (windowStartedAt === null || now - windowStartedAt > windowMs) {
      windowStartedAt = now;
      countInWindow = 0;
    }
    countInWindow += 1;
    return { exit: countInWindow > limit, countInWindow };
  };
}

if (require.main === module) {
  const shouldExitOnUncaught = createUncaughtExceptionLimiter();

  process.on('uncaughtException', (err) => {
    console.error(`[session-host] Uncaught exception: ${err?.message}\n${err?.stack || ''}`);
    const { exit, countInWindow } = shouldExitOnUncaught(Date.now());
    if (!exit) return;
    // Repeated faults in one window: the process is wedged, not hiccuping.
    console.error(
      `[session-host] ${countInWindow} uncaught exceptions within ` +
        `${UNCAUGHT_EXCEPTION_WINDOW_MS / 1000}s (limit ${UNCAUGHT_EXCEPTION_LIMIT}); shutting down.`,
    );
    removeSessionHostPid(SESSION_HOST_APP_NAME);
    process.exit(1);
  });
  process.on('unhandledRejection', (reason: any) => {
    console.error(`[session-host] Unhandled rejection: ${reason?.message || reason}`);
  });

  void main().catch((error) => {
    console.error(error instanceof Error ? error.message : error);
    process.exit(1);
  });
}
